package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen2Test {

    @Test
    public void testNormalizedStandard_NoYearsOrMonths() {
        // Test with only days and hours to ensure basic millis calculation works
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8); // Y, M, W, D, H, M, S, MS
        // Since Y and M are 0, the if (years != 0 || months != 0) block should be skipped
        Period result = period.normalizedStandard(PeriodType.dayTime());

        assertEquals(1, result.getDays());
        assertEquals(2, result.getHours());
        assertEquals(3, result.getMinutes());
        assertEquals(4, result.getSeconds());
        assertEquals(5, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_WithYearsAndMonthsSupported() {
        // Test normalization where both years and months are supported by the PeriodType
        Period period = new Period(1, 14, 0, 0, 0, 0, 0, 0); // 1 year, 14 months = 2 years, 2 months
        Period result = period.normalizedStandard(PeriodType.yearMonthTime());

        assertEquals(2, result.getYears());
        assertEquals(2, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_WithOnlyMonthsSupported() {
        // Test normalization where years are not supported, but months are
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0); // 1 year, 2 months = 14 months
        Period result = period.normalizedStandard(PeriodType.monthTime());

        assertEquals(0, result.getYears());
        assertEquals(14, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_WithOnlyYearsSupported() {
        // Test normalization where months are not supported, but years are
        // Note: The logic calculates totalMonths = years * 12 - months. 
        // If period is 1 year, 2 months: 1*12 - 2 = 10. 
        // Wait, the implementation has a specific logic: totalMonths = years * 12L - months;
        // Let's trace: years=1, months=2 -> totalMonths = 12 - 2 = 10. 
        // normalizedYears = 10 / 12 = 0.
        // result.withYears(0).
        // totalMonths = 10 - 0 = 10.
        // Since months not supported, it checks if totalMonths != 0 and throws exception.

        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        try {
            period.normalizedStandard(PeriodType.yearTime());
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Unable to normalize"));
        }
    }

    @Test
    public void testNormalizedStandard_UnsupportedOperationException() {
        // Test the case where years/months exist but the type doesn't support them to normalize them
        // Example: Period has 1 year, but type only supports days.
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0);

        // PeriodType.dayTime() does not support YEARS_TYPE or MONTHS_TYPE
        try {
            period.normalizedStandard(PeriodType.dayTime());
            fail("Expected UnsupportedOperationException because years exist but type doesn't support years/months");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Unable to normalize"));
        }
    }

    @Test
    public void testNormalizedStandard_NegativeValues() {
        // Test with negative years/months to cover branch coverage for totalMonths calculation
        // years = -1, months = -2. totalMonths = (-1 * 12) - (-2) = -12 + 2 = -10.
        Period period = new Period(-1, -2, 0, 0, 0, 0, 0, 0);
        Period result = period.normalizedStandard(PeriodType.yearMonthTime());

        assertEquals(-1, result.getYears()); // totalMonths / 12 = -10 / 12 = 0 in integer math? 
        // Actually, in Java -10 / 12 = 0.
        // Let's re-verify: totalMonths = -10. normalizedYears = 0. result = result.withYears(0).
        // totalMonths = -10 - 0 = -10. normalizedMonths = -10. result = result.withMonths(-10).
        // Result should be 0 years, -10 months.
        assertEquals(0, result.getYears());
        assertEquals(-10, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_LargeMillis() {
        // Test to ensure the long millis calculation doesn't overflow prematurely
        // Using large values for days and weeks
        Period period = new Period(0, 0, 1000000, 1000000, 0, 0, 0, 0);
        Period result = period.normalizedStandard(PeriodType.millisTime());

        // If it doesn't throw or crash, the long millis addition worked.
        assertNotNull(result);
    }
}
